I created a data structure that stores the scores of a high score list. The data structure is a linked list, where each node represents a score and its corresponding player name. The linked list is sorted in descending order based on the scores. The data structure also includes a method for adding a new score and player name to the list, and a method for retrieving the top 10 scores and player names.

### Code:
```python
class ScoreList:
    def __init__(self):
        self.head = None

    def add_score(self, score, player_name):
        new_node = Node(score, player_name)
        if self.head is None:
            self.head = new_node
        else:
            current = self.head
            while current.next is not None:
                current = current.next
            current.next = new_node

    def get_top_scores(self):
        top_scores = []
        current = self.head
        while current is not None:
            top_scores.append(current.score)
            current = current.next
        return top_scores[:10]

    def get_top_players(self):
        top_players = []
        current = self.head
        while current is not None:
            top_players.append(current.player_name)
            current = current.next
        return top_players[:10]

class Node:
    def __init__(self, score, player_name):
        self.score = score
        self.player_name = player_name
        self.next = None
