```java
public class Heap {
    private int[] heap;
    private int size;

    public Heap(int size) {
        heap = new int[size];
        this.size = 0;
    }

    public void insert(int value) {
        heap[size++] = value;
        int index = size - 1;
        while (index > 0) {
            int parent = (index - 1) / 2;
            if (heap[parent] < heap[index]) {
                int temp = heap[parent];
                heap[parent] = heap[index];
                heap[index] = temp;
                index = parent;
            } else {
                break;
            }
        }
    }

    public int remove() {
        if (size == 0) {
            return -1;
        }
        int result = heap[0];
        heap[0] = heap[--size];
        int index = 0;
        while (index < size) {
            int left = 2 * index + 1;
            int right = 2 * index + 2;
            if (left >= size) {
                break;
            }
            if (right >= size) {
                if (heap[index] < heap[left]) {
                    int temp = heap[index];
                    heap[index] = heap[left];
                    heap[left] = temp;
                    index = left;
                } else {
                    break;
                }
            } else {
                if (heap[index] < heap[left] && heap[index] < heap[right]) {
                    int temp = heap[index];
                    heap[index] = heap[left] < heap[right] ? heap[right] : heap[left];
                    heap[left] = temp;
                    index = left;
                } else if (heap[left] < heap[right]) {
                    int temp = heap[index];
                    heap[index] = heap[left];
                    heap[left] = temp;
                    index = left;
                } else {
                    break;
                }
            }
        }
        return result;
    }

    public void print() {
        for (int i = 0; i < size; i++) {
            System.out.print(heap[i] + " ");
        }
        System.out.println();
    }
}
```

